import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        double x = sc.nextDouble();
        double y = sc.nextDouble();
        int n = sc.nextInt();

        double min = 2e9;
        double mod = x / y;
        double ax = 0, ay = 0;
        for (int i = 1; i <= n; i++) {
            double a = Math.round(mod * i + 0.4999);
            double t1 = Math.abs(a / i - mod);
            if (t1 < min) {
                min = t1;
                ax = a;
                ay = i;
            }
        }
        System.out.println((long)ax + "/" + (long)ay);
    }
}
